from fractions import Fraction
import itertools

R = Fraction(7, 335)
solutions = []

def find_solutions(m, upper_bound):
    solutions_m = []
    # Iterate over distinct combinations of a_i, starting from a_i >= 2
    for combo in itertools.combinations(range(2, upper_bound + 1), m):
        product = 1
        for a in combo:
            product *= Fraction(a - 1, a)

        if product == R:
            solutions_m.append(list(combo))
    return solutions_m

